; Tengen Tetris -- the ROM bank: the NES RAM ($0000-$07FF), the support area below $8000 and the
; 32KB PRG-ROM at $8000-$FFFF, at its NES addresses (rom_code.s, generated by tools/convert.js).
; The cartridge is CNROM: the PRG is fixed, so this is the only ROM bank.  It also holds the two CHR-ROM
; banks.

            mx    %11

            put   ram.s                       ; The RAM map and the game constants (generated)

HORIZONTAL_MIRRORING equ $01                  ; From core/Defs.s, which is not put in the ROM segment
VERTICAL_MIRRORING   equ $02

ROMBase     ENT
            ds    $1000-*                     ; The NES RAM ($0000-$07FF)

; The CHR-ROM, both 8KB banks (CNROM).  The game's PRE_RENDER (CheckCHRBank, Main.s) copies the bank the
; ROM selects (ppu_bank) into the PPU's CHR_ROM.
CHR_BANKS   ENT
            putbin chr0.bin                   ; Bank 0: the menus and the game
CHR_BANK1   ENT
            putbin chr1.bin                   ; Bank 1: the title screen and the leaderboard

            ds    $6000-*

y_exclude   ENT                               ; Table of excluded sprite Y values -- filled in by InitYExclude at start-up
            ds    256

tile_exclude ENT                              ; Table of excluded tiles (none)
            ds    256

            put  Config.s                      ; HAS_CHR_RAM and the other engine constants rom_inject.s tests
            put  ../../ppu/ppu_reg_vars.s  ; PPU state, only put in the base ROM bank
            put   ../../rom/rom_inject.s      ; The PPU / APU register hooks
            put   abs_y.s                     ; The abs,Y helpers for the NES zero page (generated)
            put   support.s                   ; The routines the patches call

            ds    $8000-*
            put   rom_code.s                  ; $8000-$FFFF (generated)
